WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessions_sessions AS (SELECT id, device, browser, started_at, SUM(new_group_flag) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT id, device, browser, started_at FROM sessions_sessions ORDER BY id DESC
